const CardContext = createContext<{ size: 'sm' | 'lg' } | null>(null);

export function Card({ size = 'sm', children }: CardProps) {
  return (
    <CardContext.Provider value={{ size }}>
      <div className="card">{children}</div>
    </CardContext.Provider>
  );
}

Card.Header = function Header({ children }: { children: ReactNode }) {
  const ctx = useContext(CardContext);
  return <div className={`card-header ${ctx!.size}`}>{children}</div>;
};

Card.Body = ({ children }: { children: ReactNode }) =>
  <div className="card-body">{children}</div>;
